'use strict';
function v3ReadSession(key){try{return typeof sessionStorage==='undefined'?null:sessionStorage.getItem(key)}catch{return null}}
function v3SessionSet(key,value){try{if(typeof sessionStorage==='undefined')return;if(value==null)sessionStorage.removeItem(key);else sessionStorage.setItem(key,value)}catch{}}
function v3InitialIdentity(){if(!window.RAINWISE_ENTRY_GATE)return stored('sy-v3-role');const navigation=typeof performance!=='undefined'&&typeof performance.getEntriesByType==='function'?performance.getEntriesByType('navigation')[0]:null;if(navigation?.type==='navigate'){v3SessionSet('sy-v17-session-role',null);return null}return v3ReadSession('sy-v17-session-role')}
function v3SaveIdentity(role){V3.role=role;save('sy-v3-role',role);v3SessionSet('sy-v17-session-role',role)}
const V3={role:v3InitialIdentity(),chosen:window.RAINWISE_ENTRY_GATE?null:'user',page:v3ReadSession('sy-v17-maint-page')||'workspace',filter:'全部',severity:'全部',search:''};
if(!['user','maintainer'].includes(V3.role))V3.role=null;
const V3NAV=[['workspace','维护总览','layers'],['feedback','灾情核验','message'],['tasks','任务审核','layers'],['materials','材料申请','layers'],['software','软件维护','shield'],['hazards','隐患资料','map'],['logs','操作记录','clock']];
const V3STATUS=['待核验','核验中','已核验','已更新','已关闭'];
const v3Feedback=()=>stored('sy-v2-feedback');
const v3Urgent=f=>f.priority==='加急'||f.severity==='疑似紧急危险';
function v3Log(action,id,detail){const rows=stored('sy-v3-logs');rows.push({id:vId(),time:businessNow().toISOString(),actor:'维护人员 · 游客体验',action,record_id:id,detail});save('sy-v3-logs',rows.slice(-200));}
function v3FeedbackProgress(f){return `<div class="feedbackprogress"><span class="done">已保存在本地</span> → <span class="done">${esc(f.status||'待核验')}</span>${f.handled_at?`<br><small>更新 ${esc(dateText(f.handled_at))} · 维护端记录</small>`:''}</div>${f.handling_note?`<div class="handlingnote"><b>处理说明</b><p data-original>${esc(f.handling_note)}</p>${f.evidence_url&&/^https?:\/\//.test(f.evidence_url)?`<a href="${esc(f.evidence_url)}" target="_blank" rel="noopener">核验依据 ↗</a>`:''}</div>`:''}${f.resolution?`<p class="muted">处理结果：${esc(f.resolution)}</p>`:''}`;}
function v3Entry(){return `<main class="entrypage"><header class="entryheader"><div class="entrybrand">${icon('rain',26)}<b>深雨知路</b><span>RAINWISE · LUOHU</span></div><span class="tag">体验入口 · 无需创建账号</span></header><section class="entryhero"><div class="entrycopy"><div class="eyebrow">ONE JOURNEY. MORE CONTEXT.</div><h1>每一次出行，<br><span>多一份依据。</span></h1><p>查看罗湖区暴雨出行信息，或进入维护端处理现场反馈。<br>现在只提供两种身份，两边都能以游客方式直接体验。</p><div class="entryfacts"><span>官方资料可追溯</span><span>反馈进度可查看</span><span>无需注册</span></div></div><section class="entrybox"><h2>选择你的入口</h2><p class="muted">请先选择身份。用户和维护人员都可直接体验。</p><button class="rolechoice ${V3.chosen==='user'?'selected':''}" data-v3="choose" data-value="user"><span class="roleicon">${icon('route',24)}</span><span><b>用户</b><small>查行程、比较方案、提交反馈</small></span><span class="rolecheck">${V3.chosen==='user'?'●':'○'}</span></button><button class="rolechoice ${V3.chosen==='maintainer'?'selected':''}" data-v3="choose" data-value="maintainer"><span class="roleicon">${icon('shield',24)}</span><span><b>维护人员</b><small>查看反馈、优先核验、更新处理进度</small></span><span class="rolecheck">${V3.chosen==='maintainer'?'●':'○'}</span></button><button class="primary enterbutton" data-v3="enter" ${!V3.chosen?'disabled':''}>${!V3.chosen?'请选择身份后进入':V3.chosen==='maintainer'?'进入维护人员体验':'进入用户体验'} →</button><p class="entrynote">无需手机号、邮箱或密码。这里是体验身份选择，不是已接通的账号认证；反馈与处理记录目前在同一浏览器内共享。</p></section></section><footer class="entryfooter">深圳罗湖区 · 台风暴雨出行信息助手<span>公开资料驱动 · 实时信息与共享后端待完善</span></footer></main>`;}
function v3Stats(){const f=v3Feedback();return `<div class="maintstats">${[['全部反馈',f.length,'message'],['待核验',f.filter(x=>!x.status||x.status==='待核验').length,'search'],['加急关注',f.filter(x=>v3Urgent(x)&&x.status!=='已关闭').length,'shield'],['已关闭',f.filter(x=>x.status==='已关闭').length,'clock']].map(([t,n,i],index)=>`<article class="card ${index===0?'statprimary':''}"><div class="row"><small>${t}</small>${icon(i,20)}</div><b>${n}</b><small>${index===2?'用户自评或维护加急，不是官方风险级别':'当前浏览器记录'}</small></article>`).join('')}</div>`;}
function v3List(rows){return rows.length?rows.map(f=>`<article class="maintitem"><div class="maintitemhead"><div><b>${esc(f.place)}</b><p>${esc(f.type)} · ${esc(f.basis)} · 观察 ${esc(dateText(f.observed))}</p></div><div class="chips"><span class="tag ${v3Urgent(f)?'red':'orange'}">${esc(f.severity)}</span>${v3Urgent(f)?'<span class="tag red">加急核验</span>':''}<span class="tag gray">${esc(f.status||'待核验')}</span></div></div><p data-original>${esc(f.content)}</p><div class="row"><small>提交 ${esc(dateText(f.submitted))} · 编号 ${esc(String(f.id).startsWith('v')?f.id:f.id.slice(-8))}</small><div class="chips">${f.photo?`<button data-v3="photo" data-value="${f.id}">查看现场图片</button>`:''}<button class="primary" data-v3="handle" data-value="${f.id}">查看与处理 →</button></div></div>${f.handling_note?`<div class="handlingnote"><small>最近处理说明</small><p data-original>${esc(f.handling_note)}</p></div>`:''}</article>`).join(''):'<div class="empty">没有符合条件的用户反馈。<br>切换到用户端提交一条反馈后，这里会显示同一浏览器内的真实记录。</div>'}
function v3Workspace(){const f=v3Feedback().slice().sort((a,b)=>Number(v3Urgent(b))-Number(v3Urgent(a)));return vHead('MAINTENANCE WORKSPACE','维护总览','从用户反馈到核验记录，让每一步处理可查看。',`<button data-v3="page" data-value="feedback">打开反馈队列 →</button>`)+v3Stats()+`<div class="panelgrid"><section class="card"><div class="row"><h2>优先处理队列</h2><span class="tag">按加急标记优先</span></div>${v3List(f.filter(x=>x.status!=='已关闭').slice(0,5))}</section><section class="card" style="align-self:start"><h2>处理流程</h2>${[['01','查看现场线索','地点、观察时间、图片和用户自评分别检查。'],['02','记录核验过程','补充现场复核或公开依据，不直接把反馈当官方确认。'],['03','更新处理状态','保存意见和时间，用户端同步展示进度。'],['04','需要上报时','先导出摘要，再通过正式渠道人工提交；未获得回执不显示已上报。']].map(([n,t,p])=>`<div class="listitem"><span class="tag">${n}</span> <b>${t}</b><p>${p}</p></div>`).join('')}<div class="notice">两种身份均为游客体验，没有真实账号或访问权限隔离。跨设备、多用户共享与正式后台认证尚未接通。</div><button data-v3="switch">切换到用户入口</button></section></div>`;}
function v3Queue(){const rows=v3Feedback().filter(f=>(V3.filter==='全部'||(f.status||'待核验')===V3.filter)&&(V3.severity==='全部'||(V3.severity==='加急'?v3Urgent(f):f.severity===V3.severity))&&(!V3.search||(f.place+' '+f.content).includes(V3.search))).sort((a,b)=>Number(v3Urgent(b))-Number(v3Urgent(a)));return vHead('FEEDBACK & FOLLOW-UP','用户反馈处理','用户上传的文字和图片在这里显示；自评严重程度与核验结果独立保留。',`<button data-v3="export">导出待核验摘要</button>`)+`<section class="card"><div class="maintfilters"><div class="field"><label>处理状态</label><select id="v3-filter">${['全部',...V3STATUS].map(x=>`<option ${V3.filter===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>严重程度／优先级</label><select id="v3-severity">${['全部','加急','一般影响','明显影响','疑似紧急危险'].map(x=>`<option ${V3.severity===x?'selected':''}>${x}</option>`).join('')}</select></div><form id="v3-search" class="queryform" style="margin:0;flex:1"><input name="q" placeholder="查找地点或反馈内容" value="${esc(V3.search)}"><button>筛选</button></form></div><small>${rows.length}条匹配记录 · 严重程度为用户自评，未核验前不代表客观风险等级</small>${v3List(rows)}</section>`;}
function v3Hazards(){const drafts=stored('sy-v3-hazards');return vHead('PLACE RECORDS','隐患资料','官方原始资料只读保留；维护补充记录独立标注。')+`<section class="card"><div class="row"><h2>官方指引目录 · 罗湖区</h2><span class="tag">2026版 · 10个街道</span></div><div class="tablewrap"><table><thead><tr><th>街道</th><th>原始风险描述</th><th>来源</th></tr></thead><tbody>${D.risks.filter(r=>r.guide_year===2026).map(r=>`<tr><td>${r.street}</td><td data-original>${esc(r.risk_description)}</td><td><a href="${r.source_url}" target="_blank" rel="noopener">原件 ↗</a></td></tr>`).join('')}</tbody></table></div></section><div class="panelgrid" style="margin-top:18px"><section class="card"><h2>新增维护补充记录</h2><form id="v3-hazard-form" class="feedbackform"><div class="field"><label>地点</label><input name="place" required></div><div class="field"><label>信息来源链接 · 可选</label><input name="source" type="url" placeholder="https://"></div><div class="field full"><label>隐患描述与待核实事项</label><textarea name="content" required></textarea></div><div class="full"><button class="primary">保存维护草稿</button> <small>独立记录，不覆盖官方原文</small></div></form></section><section class="card"><h2>维护补充记录</h2>${drafts.length?drafts.slice().reverse().map(x=>`<div class="listitem"><div class="row"><b>${esc(x.place)}</b><span class="tag gray">维护草稿 · 待核验</span></div><p>${esc(x.content)}</p><small>${esc(dateText(x.created))}</small>${x.source?`<br><a href="${esc(x.source)}" target="_blank" rel="noopener">补充来源 ↗</a>`:''}</div>`).join(''):'<div class="empty">尚无维护草稿。</div>'}<p class="muted">本地补充不是官方确认，当前不会自动作为出行推荐依据。</p></section></div>`;}
function v3Logs(){const rows=stored('sy-v3-logs');return vHead('ACTIVITY RECORDS','操作记录','保留处理动作、时间与说明；本地记录不作为不可篡改审计。',`<button data-v3="export-logs">导出记录</button>`)+`<section class="card"><div class="tablewrap"><table><thead><tr><th>时间</th><th>体验身份</th><th>操作</th><th>记录</th><th>说明</th></tr></thead><tbody>${rows.slice().reverse().map(x=>`<tr><td>${esc(dateText(x.time))}</td><td>${esc(x.actor)}</td><td>${esc(x.action)}</td><td>${esc(x.record_id?.slice(0,8))}</td><td>${esc(x.detail)}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">没有预填操作记录，实际处理后显示。</div>'}</div></section>`;}
function v3Maintenance(){const pages={workspace:v3Workspace,feedback:v3Queue,hazards:v3Hazards,logs:v3Logs,software:()=>v14SoftwareMaintenance(),tasks:()=>v14TaskReview(),materials:()=>v14MaterialReview()};const title=V3NAV.find(x=>x[0]===V3.page)?.[1]||'维护总览';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">${icon('rain',26)}</div><div><b>深雨知路</b><small>MAINTENANCE</small></div></div><nav class="nav">${V3NAV.map(([id,t,i])=>`<button data-v3="page" data-value="${id}" class="${V3.page===id?'active':''}" ${V3.page===id?'aria-current="page"':''}>${icon(i)}${t}</button>`).join('')}</nav><div class="sidefoot"><div class="line"></div><b>维护人员 · 游客体验</b>同一浏览器内处理用户反馈<br>不是正式权限认证<div class="chips" style="margin-top:12px"><button data-v3="switch">切换身份</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">维护端 / <b>${title}</b></div><div class="chips"><span class="tag">游客 · 维护人员</span><button data-v3="refresh">刷新当前队列</button><button data-v3="switch">切换入口</button></div></header><div class="content">${(pages[V3.page]||v3Workspace)()}<footer class="footer"><span>用户自评、维护核验和官方确认分别保留</span><span>反馈与处理记录：本浏览器共享</span></footer></div></main></div>`;}
function v3Handle(id){const f=v3Feedback().find(x=>x.id===id);if(!f)return;vDialog('反馈详情与处理',`<div class="sourceoriginal"><b>${esc(f.place)}</b><p data-original>${esc(f.content)}</p><small>观察 ${esc(dateText(f.observed))}<br>提交 ${esc(dateText(f.submitted))}<br>${esc(f.basis)} · 用户自评 ${esc(f.severity)}</small></div>${f.photo?`<button style="margin-top:12px" data-v3="photo" data-value="${f.id}">查看现场图片</button>`:''}<form id="v3-handle-form" class="feedbackform"><input name="id" type="hidden" value="${f.id}"><div class="field"><label>处理状态</label><select name="status">${V3STATUS.map(s=>`<option ${(f.status||'待核验')===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>处理优先级</label><select name="priority"><option ${f.priority!=='加急'?'selected':''}>普通</option><option ${f.priority==='加急'?'selected':''}>加急</option></select></div><div class="field"><label>核验结论</label><select name="conclusion">${['尚未形成结论','属实（核对范围内）','部分属实','不属实','资料不足'].map(c=>`<option ${f.conclusion===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field full"><label>核验依据／处理意见</label><textarea name="note" required placeholder="记录检查了什么、哪些仍待确认">${esc(f.handling_note||'')}</textarea></div><div class="field full"><label>依据链接 · 可选</label><input name="evidence" type="url" value="${esc(f.evidence_url||'')}" placeholder="https://"></div><div class="field full"><label>处理结果／下一步 · 可选</label><textarea name="resolution">${esc(f.resolution||'')}</textarea></div><div class="full"><button class="primary">保存处理进度</button></div></form><div class="notice">“已核验”记录维护端的复核声明，不自动成为官方确认；没有提交渠道和回执，不显示已上报。</div>`);}
const v3UserRender=vRender;
vRender=function(){if(!V3.role){$('#app').innerHTML=v3Entry();return}if(V3.role==='maintainer'){v3Maintenance();return}v3UserRender();const top=document.querySelector('.topbar');if(top)top.insertAdjacentHTML('beforeend','<button class="rolebadge" data-v3="switch">用户 · 游客体验 ⇄</button>');const foot=document.querySelector('.sidefoot');if(foot)foot.insertAdjacentHTML('beforeend','<div style="margin-top:14px"><button data-v3="switch">切换入口</button></div>');};
document.addEventListener('click',e=>{const b=e.target.closest('[data-v3]');if(!b)return;const a=b.dataset.v3,v=b.dataset.value;if(a==='choose'){V3.chosen=v;vRender();return}if(a==='enter'){if(!['user','maintainer'].includes(V3.chosen))return toast('请先选择身份');v3SaveIdentity(V3.chosen);if(V3.role==='maintainer'){V3.page='workspace';v3SessionSet('sy-v17-maint-page','workspace')}document.getElementById('source-dialog')?.close();if(typeof v14Guide==='function'&&window.RAINWISE_ENTRY_GATE){if(!v3ReadSession('sy-v19-guide-'+V3.role)){v3SessionSet('sy-v19-guide-'+V3.role,'seen');v14Guide(0);return}vRender();return}vRender();return}if(a==='switch'){vDraft();v3SaveIdentity(null);V3.chosen=null;if(typeof V14!=='undefined')V14.guideIndex=null;document.getElementById('source-dialog')?.close();vRender();return}if(a==='page'){V3.page=v;v3SessionSet('sy-v17-maint-page',v);window.scrollTo(0,0);}if(a==='refresh')toast('已读取当前浏览器反馈');if(a==='handle')return v3Handle(v);if(a==='photo')return vPhotoDialog(v);if(a==='export'){download('深雨知路_维护反馈摘要.json',JSON.stringify({status:'本地维护记录，未自动提交官方',feedback:v3Feedback().map(({photo,...f})=>f)},null,2),'application/json');return}if(a==='export-logs'){download('深雨知路_维护操作记录.json',JSON.stringify(stored('sy-v3-logs'),null,2),'application/json');return}vRender();});
document.addEventListener('change',e=>{if(vFormId(e.target)==='v3-filter')V3.filter=e.target.value;else if(vFormId(e.target)==='v3-severity')V3.severity=e.target.value;else return;vRender();});
document.addEventListener('submit',e=>{const f=e.target;if(!vFormId(f).startsWith('v3-'))return;e.preventDefault();const x=Object.fromEntries(new FormData(f));if(vFormId(f)==='v3-search'){V3.search=x.q.trim();vRender();return}if(V3.role!=='maintainer')return toast('请进入维护体验端操作');if(vFormId(f)==='v3-handle-form'){if(!V3STATUS.includes(x.status))return toast('处理状态无效');if(!x.note?.trim())return toast('请记录核验依据或处理意见');if(x.evidence&&!/^https?:\/\//.test(x.evidence))return toast('依据链接仅支持http或https');const rows=v3Feedback(),record=rows.find(r=>r.id===x.id);if(!record)return toast('反馈记录已不存在');if(['已核验','已更新'].includes(x.status)&&(!x.conclusion||x.conclusion==='尚未形成结论'))return toast('请填写核验结论');const old=record.status||'待核验';const timeline=typeof v9Versions==='function'?[...v9Versions(record)]:[...(record._timeline||[{time:record.submitted,state:{status:old}}])];Object.assign(record,{status:x.status,conclusion:x.conclusion||'尚未形成结论',priority:x.priority==='加急'?'加急':'普通',handling_note:x.note.trim(),evidence_url:x.evidence||'',resolution:x.resolution||'',handled_at:businessNow().toISOString(),actual_handled_at:new Date().toISOString(),handled_by:'维护人员 · 游客体验'});record._timeline=[...timeline,{time:businessNow().toISOString(),state:typeof v9StateOf==='function'?v9StateOf(record):{status:record.status,conclusion:record.conclusion,handling_note:record.handling_note,resolution:record.resolution,evidence_url:record.evidence_url}}];if(save('sy-v2-feedback',rows)){if(typeof v16Notify==='function')v16Notify('feedback',record.demo?'演示灾情核验进度':'灾情核验进度更新',record.place+'：'+record.status+(record.resolution?'；'+record.resolution:''));v3Log('更新反馈处理',record.id,`${old} → ${record.status}；${record.priority}；${record.handling_note}`);$('#source-dialog').close();toast('处理进度已保存，用户端可查看');vRender();}}if(vFormId(f)==='v3-hazard-form'){if(x.source&&!/^https?:\/\//.test(x.source))return toast('来源仅支持http或https');const rows=stored('sy-v3-hazards'),record={id:vId(),place:x.place.trim(),content:x.content.trim(),source:x.source||'',created:new Date().toISOString(),status:'维护草稿，待核验'};rows.push(record);if(save('sy-v3-hazards',rows)){v3Log('新增维护草稿',record.id,record.place);toast('维护草稿已保存，未覆盖官方资料');vRender();}}});
window.addEventListener('storage',e=>{if(['sy-v2-feedback','sy-v3-hazards','sy-v3-logs'].includes(e.key))vRender();});
vRender();
